Процедура ПриНачалеРаботыСистемы()
    КоличествоЗаявок = 4;
    Итог = 0;
    Номер = 1;
    Пока Номер <= КоличествоЗаявок Цикл
        Итог = Итог + Номер;
        Номер = Номер + 1;
    КонецЦикла;
    Сообщить(Итог);
КонецПроцедуры
